		run.behaviorDigest = witnessAngularSuperProductivityBehaviorDigest(
			run,
			DECLARED_DIFFERENCE_LABELS,
		);
	}
	receipt.integrity.canonicalDigest = witnessAngularSuperProductivityDigest(receipt);
