30			expect(spec.app).toBe(ANGULAR_SUPER_PRODUCTIVITY_APP);
31			expect(spec.framework).toBe('angular');
32			const bound = Object.fromEntries(
33				ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.map((receipt) => [
34					receipt.lane,
35					receipt.canonicalRoot,
36				]),
37			);
38			// The lane roots the spec serves must END with the canonical output root
39			// the schema pins for that lane; serving a sibling would be serving one
40			// build rather than the lane the bound record describes.
